style.css:
/* Make the background darker */
body, html {
    background-color: #0a0a0a !important;
    color: #003366 !important; /* Dark blue text */
}

/* Target specific elements for text color */
p, h1, h2, h3, h4, h5, h6, span, div {
    color: #003366 !important; /* Ensures text is dark blue */
}

/* Darken other elements */
header, footer, nav, aside, section, article {
    background-color: #121212 !important;
}

/* Adjust links */
a {
    color: #0055aa !important; /* Slightly brighter dark blue for links */
}
a:hover {
    color: #0077cc !important; /* Even brighter on hover */
}
